CREATE TABLE IF NOT EXISTS reader_eval_campaigns(id TEXT PRIMARY KEY,actor TEXT NOT NULL,manifest_hash TEXT NOT NULL,baseline_at TEXT NOT NULL,baseline_openai_nano INTEGER NOT NULL,limit_nano INTEGER NOT NULL,busy TEXT,halted TEXT,failures INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reader_eval_cells(campaign_id TEXT NOT NULL,id TEXT NOT NULL,ordinal INTEGER NOT NULL,model TEXT NOT NULL,text_sha256 TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',body_sha256 TEXT,result_json TEXT,PRIMARY KEY(campaign_id,id),UNIQUE(campaign_id,ordinal));
CREATE TABLE IF NOT EXISTS reader_eval_attempts(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL,cell_id TEXT NOT NULL,body_sha256 TEXT NOT NULL,model_requested TEXT NOT NULL,model_returned TEXT,state TEXT NOT NULL,cost_nano INTEGER,raw_key TEXT,metadata_key TEXT,usage_json TEXT,status INTEGER,latency_ms INTEGER,request_id TEXT,created_at TEXT NOT NULL);
